"""Passive diagnostics for actual database concurrency acceptance only."""
SQL_OBSERVER="\nimport traceback\nfrom sqlalchemy import event\nfrom app.db import engine\nsql_active={}\ndef sql_emit(value):\n    with (root/'sql-observation.jsonl').open('a',encoding='utf-8') as f:\n        f.write(json.dumps(dict(at=time.monotonic(),**value))+'\\n')\ndef sql_task():\n    t=asyncio.current_task()\n    return id(t) if t else None\n@event.listens_for(engine.sync_engine,'before_cursor_execute')\ndef before_sql(conn,cursor,statement,parameters,context,many):\n    # Never record SQL text or parameters: only the operation and call sites.\n    op=statement.lstrip().split(None,1)[0].upper()\n    if op in {'UPDATE','INSERT','DELETE','BEGIN'}:\n        context.observed_start=time.monotonic()\n        sql_emit({'event':'waiting','connection':id(conn),'task':sql_task(),'operation':op,\n            'stack':[x.filename+':'+x.name+':'+str(x.lineno) for x in traceback.extract_stack() if '/app/' in x.filename.replace('\\\\','/')]})\n@event.listens_for(engine.sync_engine,'after_cursor_execute')\ndef after_sql(conn,cursor,statement,parameters,context,many):\n    if hasattr(context,'observed_start'):\n        sql_active.setdefault(id(conn),{'since':time.monotonic(),'task':sql_task()})\n        sql_emit({'event':'acquired','connection':id(conn),'task':sql_task(),'elapsed':time.monotonic()-context.observed_start})\n@event.listens_for(engine.sync_engine,'commit')\ndef commit_sql(conn):\n    sql_active.pop(id(conn),None);sql_emit({'event':'commit','connection':id(conn),'task':sql_task()})\n@event.listens_for(engine.sync_engine,'rollback')\ndef rollback_sql(conn):\n    sql_active.pop(id(conn),None);sql_emit({'event':'rollback','connection':id(conn),'task':sql_task()})\nasync def sql_watch():\n    while True:\n        await asyncio.sleep(1)\n        held=[dict(connection=k,**v,age=time.monotonic()-v['since']) for k,v in sql_active.items()]\n        if any(x['age']>3 for x in held):\n            sql_emit({'event':'held','connections':held})\n            p=root/'task-observation.json'\n            if p.exists():(root/('held-tasks-'+str(int(time.monotonic()))+'.json')).write_bytes(p.read_bytes())\n@app.on_event('startup')\nasync def sql_start():asyncio.create_task(sql_watch())\n"
